#!/usr/bin/env node
/**
 * synthesis-x402-commerce-mcp demo
 * Shows x402 payment flow + product extraction via MCP
 *
 * Usage: node demo/demo.js
 */

const MCP_ENDPOINT = 'https://podcast-commerce-mcp.sincetoday.workers.dev/mcp';
const DEMO_TRANSCRIPT = `Today's episode is sponsored by AG1. I've been taking it every morning for 6 months.
My Oura Ring confirms my sleep quality has improved significantly since I started.
I also use Rogue Fitness equipment for my home gym setup — worth every penny.`;

/**
 * Parse a Cloudflare Worker SSE/Streamable HTTP response.
 * Workers return: "data: {json}\n\n" — not raw JSON.
 */
async function parseWorkerResponse(response) {
  const text = await response.text();
  // Try raw JSON first (handles any non-SSE endpoints)
  try {
    return JSON.parse(text);
  } catch {
    // Parse SSE: find lines starting with "data: "
    for (const line of text.split('\n')) {
      if (line.startsWith('data: ')) {
        try {
          return JSON.parse(line.slice(6));
        } catch {}
      }
    }
    throw new Error(`Could not parse worker response: ${text.substring(0, 200)}`);
  }
}

async function callMCPTool(endpoint, toolName, args, apiKey = null) {
  const headers = {
    'Content-Type': 'application/json',
    'Accept': 'application/json, text/event-stream',
  };

  if (apiKey) {
    headers['X-API-Key'] = apiKey;
  }

  const body = JSON.stringify({
    jsonrpc: '2.0',
    id: 1,
    method: 'tools/call',
    params: {
      name: toolName,
      arguments: args
    }
  });

  const response = await fetch(endpoint, {
    method: 'POST',
    headers,
    body,
  });

  if (response.status === 402) {
    const paymentRequired = await parseWorkerResponse(response);
    return { status: 402, paymentRequired };
  }

  const result = await parseWorkerResponse(response);
  return { status: response.status, result };
}

async function main() {
  console.log('=== synthesis-x402-commerce-mcp Demo ===\n');
  console.log('Endpoint:', MCP_ENDPOINT);
  console.log('ERC-8004 Registration: https://basescan.org/tx/0x6524136b51cf57034f2970ab58236095e889c9f2135b66082ffeefe9bc33d3cc\n');

  // Step 1: List available tools
  console.log('Step 1: Discovering tools via MCP...');
  const listResponse = await fetch(MCP_ENDPOINT, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream' },
    body: JSON.stringify({ jsonrpc: '2.0', id: 1, method: 'tools/list', params: {} })
  });

  if (listResponse.ok) {
    const toolsData = await parseWorkerResponse(listResponse);
    const tools = toolsData.result?.tools || [];
    console.log(`Found ${tools.length} tools: ${tools.map(t => t.name).join(', ')}\n`);
  }

  // Step 2: Call extract_podcast_products (free tier — no payment needed for first 200 calls/day)
  console.log('Step 2: Calling extract_podcast_products (free tier, 200 calls/day)...');
  console.log('Input transcript:', DEMO_TRANSCRIPT.substring(0, 80) + '...\n');

  const extractResult = await callMCPTool(MCP_ENDPOINT, 'extract_podcast_products', {
    transcript: DEMO_TRANSCRIPT,
    show_name: 'Health Optimization Podcast',
    episode_id: 'demo-2026-03-18'
  });

  if (extractResult.status === 402) {
    console.log('x402 Payment Required!');
    console.log('Payment details:', JSON.stringify(extractResult.paymentRequired, null, 2));
    console.log('\nTo pay: construct a signed USDC transfer on Base Mainnet');
    console.log('Asset: 0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913 (USDC on Base)');
    console.log('Amount: 10000 (= $0.01 USDC)');
    console.log('After payment: retry with X-PAYMENT header containing signed proof\n');
  } else if (extractResult.status === 200) {
    const products = extractResult.result?.result?.content?.[0]?.text;
    if (products) {
      try {
        const parsed = JSON.parse(products);
        console.log('Extracted products:');
        (parsed.products || []).forEach(p => {
          console.log(`  - ${p.name} (brand: ${p.brand || 'unknown'}, confidence: ${p.confidence}, sponsored: ${p.is_sponsored})`);
        });
        console.log(`\nExtraction metadata:`);
        if (parsed.extraction_metadata) {
          console.log(`  Model: ${parsed.extraction_metadata.model}`);
          console.log(`  Latency: ${parsed.extraction_metadata.latency_ms}ms`);
          console.log(`  Cost: $${parsed.extraction_metadata.cost_usd}`);
        }
      } catch (e) {
        console.log('Raw output:', products.substring(0, 500));
      }
    }
  }

  console.log('\n=== x402 Payment Flow ===');
  console.log('1. Agent calls tool → receives 402 with x402 header');
  console.log('2. Agent signs USDC transfer on Base Mainnet');
  console.log('3. Agent retries with X-PAYMENT proof header');
  console.log('4. Tool executes, payment recorded on-chain');
  console.log('5. Basescan verifies: https://basescan.org/tx/0x6524136b51cf57034f2970ab58236095e889c9f2135b66082ffeefe9bc33d3cc');
  console.log('\nFree tier: 200 calls/day. After that: $0.01/call USDC on Base.');
}

main().catch(console.error);

/**
 * register-reputation.js
 * Submits a self-reported feedback entry to ERC-8004 ReputationRegistry on Base Mainnet.
 *
 * Prerequisites:
 *   npm install
 *   PRIVATE_KEY=0x... node scripts/register-reputation.js
 *
 * Gas cost: ~$0.01-0.03 in ETH on Base Mainnet
 */

import { ethers } from 'ethers';
import { createHash } from 'crypto';

// ERC-8004 contracts on Base Mainnet
const REPUTATION_REGISTRY = '0x8004BAa17C55a88189AE136b182e5fdA19dE9b63';
const BASE_RPC = 'https://mainnet.base.org';

// Our agent identity from IdentityRegistry (participantId as uint256)
const AGENT_ID = 33453n; // ERC-721 tokenId from IdentityRegistry (not participantId)

const ABI = [
  'function giveFeedback(uint256 agentId, int128 value, uint8 valueDecimals, string tag1, string tag2, string endpoint, string feedbackURI, bytes32 feedbackHash) external',
  'function getSummary(uint256 agentId) external view returns (uint256 count, int256 sum, uint8 decimals)',
];

async function main() {
  const privateKey = process.env.PRIVATE_KEY;
  if (!privateKey) {
    console.error('Error: PRIVATE_KEY env var required (wallet that holds Base ETH for gas)');
    process.exit(1);
  }

  const provider = new ethers.JsonRpcProvider(BASE_RPC);
  const signer = new ethers.Wallet(privateKey, provider);

  const balance = await provider.getBalance(signer.address);
  console.log('Wallet:  ', signer.address);
  console.log('Balance: ', ethers.formatEther(balance), 'ETH');

  if (balance === 0n) {
    console.error('Error: wallet has 0 ETH on Base Mainnet. Fund with ~0.001 ETH for gas.');
    process.exit(1);
  }

  const registry = new ethers.Contract(REPUTATION_REGISTRY, ABI, signer);

  // Reputation parameters -- self-reported performance signal
  const value = 95;              // 95/100 reliability score
  const valueDecimals = 0;
  const tag1 = 'x402-payment';  // payment protocol used
  const tag2 = 'mcp-tools';     // capability category
  const endpoint = 'https://podcast-commerce-mcp.sincetoday.workers.dev/mcp';
  const feedbackURI = 'https://raw.githubusercontent.com/teamsincetoday/synthesis-x402-commerce-mcp/main/agent.json';

  // Deterministic hash of feedback content
  const feedbackPayload = JSON.stringify({
    agentId: AGENT_ID.toString(),
    value,
    tag1,
    tag2,
    endpoint,
    timestamp: '2026-03-19T00:00:00Z',
  });
  const hashHex = createHash('sha256').update(feedbackPayload).digest('hex');
  const feedbackHashBytes32 = '0x' + hashHex.padStart(64, '0');

  console.log('\nSubmitting reputation feedback to ERC-8004 ReputationRegistry...');
  console.log('  agentId:     ', AGENT_ID.toString());
  console.log('  value:       ', value, '(decimals:', valueDecimals, ')');
  console.log('  tags:        ', tag1, ',', tag2);
  console.log('  endpoint:    ', endpoint);
  console.log('  feedbackURI: ', feedbackURI);

  const tx = await registry.giveFeedback(
    AGENT_ID, value, valueDecimals, tag1, tag2, endpoint, feedbackURI, feedbackHashBytes32
  );

  console.log('\nTx submitted:', tx.hash);
  console.log('Basescan:    ', 'https://basescan.org/tx/' + tx.hash);
  console.log('Waiting for confirmation...');

  const receipt = await tx.wait(1);
  console.log('Confirmed! Block:', receipt.blockNumber);
  console.log('\nReputation entry registered on ERC-8004 ReputationRegistry');
  console.log('Add this tx to agent_log.json as onchain_reputation_tx:', tx.hash);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
